"""Tests for shot_detector.py — video shot boundary detection and keyframe extraction.

Verifies:
- Script runs successfully on the example video
- shots.json has correct structure and plausible shot boundaries
- contact_sheet.png exists, has correct layout and dimensions
"""

import json
import subprocess
import sys
from pathlib import Path

import numpy as np

# Ground truth for the example video (generated by generate_video.py)
# Shot spec: (start_frame, end_frame, transition_after)
# Tolerances: cuts ±4 frames, fades ±10 frames
EXAMPLE_SHOTS = [
    (0, 89, "cut"),       # Shot 0: red circle
    (90, 179, "cut"),     # Shot 1: green square
    (180, 239, "fade"),   # Shot 2: blue triangle → fade to next
    (270, 359, "cut"),    # Shot 3: yellow diamond
    (360, 419, "fade"),   # Shot 4: magenta star → fade to next
    (450, 539, "cut"),    # Shot 5: dark gray cross
]
EXAMPLE_TOTAL_FRAMES = 540
EXAMPLE_FPS = 30.0
EXAMPLE_NUM_SHOTS = 6

# Fade frames (these should NOT be assigned to any shot)
EXAMPLE_FADE_FRAMES = [(240, 269), (420, 449)]

CUT_TOLERANCE = 5
FADE_TOLERANCE = 12


def _run_detector(video_path):
    """Run shot_detector.py and return (returncode, stdout, stderr)."""
    return subprocess.run(
        [sys.executable, "/app/shot_detector.py", str(video_path)],
        capture_output=True,
        text=True,
        cwd="/app",
        timeout=120,
    )


def _load_shots():
    """Load and validate shots.json."""
    path = Path("/app/shots.json")
    assert path.exists(), "shots.json was not created"
    with open(path) as f:
        data = json.load(f)
    assert "total_frames" in data, "shots.json missing 'total_frames'"
    assert "fps" in data, "shots.json missing 'fps'"
    assert "shots" in data, "shots.json missing 'shots'"
    assert isinstance(data["shots"], list), "'shots' must be a list"
    assert len(data["shots"]) > 0, "No shots detected"
    for shot in data["shots"]:
        for field in ["shot_id", "start_frame", "end_frame", "transition_after", "keyframe_frame"]:
            assert field in shot, f"Shot {shot.get('shot_id', '?')} missing field '{field}'"
        assert shot["transition_after"] in ("cut", "fade"), \
            f"transition_after must be 'cut' or 'fade', got '{shot['transition_after']}'"
        assert shot["start_frame"] <= shot["end_frame"], \
            f"Shot {shot['shot_id']}: start_frame > end_frame"
        assert shot["start_frame"] <= shot["keyframe_frame"] <= shot["end_frame"], \
            f"Shot {shot['shot_id']}: keyframe_frame {shot['keyframe_frame']} not in [{shot['start_frame']}, {shot['end_frame']}]"
    return data


def test_script_exists():
    """Verify shot_detector.py exists."""
    assert Path("/app/shot_detector.py").exists(), "shot_detector.py does not exist"


def test_detector_runs_successfully():
    """Verify shot_detector.py runs without errors on the example video."""
    result = _run_detector("/app/example_video.mp4")
    assert result.returncode == 0, (
        f"shot_detector.py failed with exit code {result.returncode}\n"
        f"STDERR: {result.stderr[:500]}"
    )


def test_shots_json_structure():
    """Verify shots.json has valid structure and metadata."""
    data = _load_shots()
    assert data["total_frames"] > 0, "total_frames must be positive"
    assert data["fps"] > 0, "fps must be positive"
    # Check shots are in order
    for i, shot in enumerate(data["shots"]):
        assert shot["shot_id"] == i, f"Shot at index {i} has shot_id {shot['shot_id']}"
        if i > 0:
            prev = data["shots"][i - 1]
            assert shot["start_frame"] > prev["end_frame"], (
                f"Shot {i} start_frame {shot['start_frame']} not after "
                f"shot {i-1} end_frame {prev['end_frame']}"
            )


def test_shot_count():
    """Verify the correct number of shots is detected."""
    data = _load_shots()
    assert len(data["shots"]) == EXAMPLE_NUM_SHOTS, (
        f"Expected {EXAMPLE_NUM_SHOTS} shots, got {len(data['shots'])}"
    )


def test_total_frames():
    """Verify total_frames matches the example video."""
    data = _load_shots()
    assert data["total_frames"] == EXAMPLE_TOTAL_FRAMES, (
        f"Expected {EXAMPLE_TOTAL_FRAMES} total_frames, got {data['total_frames']}"
    )


def test_fps():
    """Verify fps matches the example video."""
    data = _load_shots()
    assert abs(data["fps"] - EXAMPLE_FPS) < 0.1, (
        f"Expected fps ~{EXAMPLE_FPS}, got {data['fps']}"
    )


def test_shot_boundaries():
    """Verify shot boundaries are detected within tolerance."""
    data = _load_shots()
    shots = data["shots"]

    for i, (exp_start, exp_end, exp_trans) in enumerate(EXAMPLE_SHOTS):
        detected = shots[i]
        tolerance = FADE_TOLERANCE if exp_trans == "fade" else CUT_TOLERANCE

        assert abs(detected["start_frame"] - exp_start) <= tolerance, (
            f"Shot {i}: expected start_frame ~{exp_start}, "
            f"got {detected['start_frame']} (tolerance ±{tolerance})"
        )
        assert abs(detected["end_frame"] - exp_end) <= tolerance, (
            f"Shot {i}: expected end_frame ~{exp_end}, "
            f"got {detected['end_frame']} (tolerance ±{tolerance})"
        )


def test_transition_types():
    """Verify transition types are correctly classified."""
    data = _load_shots()
    shots = data["shots"]

    for i, (_, _, exp_trans) in enumerate(EXAMPLE_SHOTS):
        detected = shots[i]
        # Only strictly check cuts; fades can be tricky
        if exp_trans == "cut":
            assert detected["transition_after"] == "cut", (
                f"Shot {i}: expected transition 'cut', got '{detected['transition_after']}'"
            )
        # For fades, accept either 'cut' or 'fade' since they're harder to classify
        # but at minimum the solver should detect the shot exists


def test_keyframes_in_range():
    """Verify keyframes fall within their shot ranges."""
    data = _load_shots()
    for shot in data["shots"]:
        assert shot["start_frame"] <= shot["keyframe_frame"] <= shot["end_frame"], (
            f"Shot {shot['shot_id']}: keyframe {shot['keyframe_frame']} "
            f"outside [{shot['start_frame']}, {shot['end_frame']}]"
        )


def test_contact_sheet_exists():
    """Verify contact_sheet.png was created."""
    path = Path("/app/contact_sheet.png")
    assert path.exists(), "contact_sheet.png was not created"
    assert path.stat().st_size > 1000, "contact_sheet.png is too small (likely empty)"


def test_contact_sheet_dimensions():
    """Verify contact_sheet.png has correct layout dimensions.

    Expected: 3 thumbnails per row, each 160×120 with 2px white border.
    For N shots: width = 3 * 164, height = ceil(N/3) * 124.
    """
    # Use subprocess to import cv2 since it may not be available in test context
    import cv2

    img = cv2.imread("/app/contact_sheet.png")
    assert img is not None, "contact_sheet.png could not be read as an image"

    h, w = img.shape[:2]
    n_shots = EXAMPLE_NUM_SHOTS
    n_rows = (n_shots + 2) // 3  # ceil division: 6 shots → 2 rows
    expected_w = 3 * 164  # 3 thumbnails × (160 + 2*2 border)
    expected_h = n_rows * 124  # N rows × (120 + 2*2 border)

    # Allow small variations in dimensions
    assert abs(w - expected_w) <= 10, (
        f"contact_sheet.png width {w} not close to expected {expected_w}"
    )
    assert abs(h - expected_h) <= 10, (
        f"contact_sheet.png height {h} not close to expected {expected_h}"
    )


def test_contact_sheet_has_content():
    """Verify contact sheet contains actual thumbnail images, not just black."""
    import cv2

    img = cv2.imread("/app/contact_sheet.png")
    assert img is not None

    # Check that multiple cells have non-black content
    h, w = img.shape[:2]
    n_shots = EXAMPLE_NUM_SHOTS
    n_rows = (n_shots + 2) // 3

    cell_w = 164
    cell_h = 124
    thumb_w = 160
    thumb_h = 120

    non_black_cells = 0
    for row in range(n_rows):
        for col in range(3):
            shot_idx = row * 3 + col
            if shot_idx >= n_shots:
                continue
            # Check the inner thumbnail area (skip the border)
            x_start = col * cell_w + 2
            y_start = row * cell_h + 2
            if y_start + thumb_h > h or x_start + thumb_w > w:
                continue
            cell = img[y_start:y_start + thumb_h, x_start:x_start + thumb_w]
            # Check mean pixel value — if all black, mean ≈ 0
            mean_val = cell.mean()
            if mean_val > 10:  # Not pure black
                non_black_cells += 1

    assert non_black_cells >= n_shots - 1, (
        f"Only {non_black_cells}/{n_shots} thumbnail cells have visible content. "
        "Contact sheet appears mostly black."
    )


def test_imports_only_allowed():
    """Ensure shot_detector.py only imports cv2, numpy, and stdlib."""
    import ast

    path = Path("/app/shot_detector.py")
    source = path.read_text()
    tree = ast.parse(source)

    allowed_third_party = {"cv2", "numpy"}
    found_imports = set()

    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                module_name = (alias.name or "").split(".")[0]
                if module_name:
                    found_imports.add(module_name)
        elif isinstance(node, ast.ImportFrom):
            if node.module:
                module_name = node.module.split(".")[0]
                if module_name:
                    found_imports.add(module_name)

    third_party = set(m for m in found_imports if m not in sys.stdlib_module_names)
    forbidden = third_party - allowed_third_party

    assert not forbidden, (
        f"Forbidden third-party imports: {forbidden}. "
        f"Only allowed: {allowed_third_party}"
    )


def test_contact_sheet_white_borders():
    """Verify that white borders exist between thumbnail cells."""
    import cv2

    img = cv2.imread("/app/contact_sheet.png")
    assert img is not None

    h, w = img.shape[:2]
    n_shots = EXAMPLE_NUM_SHOTS
    n_rows = (n_shots + 2) // 3

    cell_w = 164
    cell_h = 124

    # Check the border pixels between cell 0 and cell 1 (vertical border at x ≈ 163)
    if w > 165:
        border_x = 163  # Approximate border between first two cells
        border_strip = img[60:65, border_x - 1:border_x + 2, :]
        mean_val = border_strip.mean()
        # White border should have high mean (> 200)
        assert mean_val > 180, (
            f"Expected white border between cells but mean pixel value is {mean_val:.0f}. "
            "Borders should be white (value near 255)."
        )